NSVGimage ** i_svg_all_curves2(char *find, char *repl){
	static NSVGimage *curves[SVG_MEDIA_SIZE];
	int i = 0;
	//char ** media = svg_media();
  
  static lua_State *L = NULL;
  if (!L){ /* init Lua engine and static structures */
		L = luaL_newstate(); /* opens Lua */
		luaL_openlibs(L); /* opens the standard libraries */
  }
  
  if (!L) return NULL;
  lua_getglobal(L, "string"); /* get library */
	lua_getfield(L, 1, "gsub"); /* and function to be called */
  
  
	
	for (i = 0; i <  SVG_MEDIA_SIZE; i++){
    curves[i] = NULL;
	
    /* using Lua, try to find match and replace pattern in text */
    lua_pushvalue(L, 2); /* function to be called in index 2 */
    lua_pushstring(L, svg_data[i]); /* input string */
    lua_pushstring(L, find); /* pattern to find */
    lua_pushstring(L, repl); /* text or pattern to replace */
    if (lua_pcall(L, 3, 2, 0) == LUA_OK){
      if (lua_isnumber(L, -1) && lua_isstring(L, -2)) { /* success */
        char *new_text = (char *)lua_tostring(L, -2);
        int n = strlen (new_text);
        
        if (n > 1) curves[i] = nsvgParse(new_text, "px", 96.0f);
        
      }
      lua_pop(L, 2); /* clear Lua stack - pop returned values */
    }
	}
  lua_close(L);
  L = NULL;
  
	return curves;
}

NSVGimage * i_svg_get_curves(int idx, char *find, char *repl){
	NSVGimage *curves;
	int i = 0;
	//char ** media = svg_media();
  
  static lua_State *L = NULL;
  if (!L){ /* init Lua engine and static structures */
		L = luaL_newstate(); /* opens Lua */
		luaL_openlibs(L); /* opens the standard libraries */
  }
  
  if (!L) return NULL;
  lua_getglobal(L, "string"); /* get library */
	lua_getfield(L, 1, "gsub"); /* and function to be called */
  
  /* using Lua, try to find match and replace pattern in text */
  lua_pushvalue(L, 2); /* function to be called in index 2 */
  lua_pushstring(L, svg_data[idx]); /* input string */
  lua_pushstring(L, find); /* pattern to find */
  lua_pushstring(L, repl); /* text or pattern to replace */
  if (lua_pcall(L, 3, 2, 0) == LUA_OK){
    if (lua_isnumber(L, -1) && lua_isstring(L, -2)) { /* success */
      char *new_text = (char *)lua_tostring(L, -2);
      int n = strlen (new_text);
      
      if (n > 1) curves = nsvgParse(new_text, "px", 96.0f);
      
    }
    lua_pop(L, 2); /* clear Lua stack - pop returned values */
  }
	
  lua_close(L);
  L = NULL;
  
	return curves;
}

NSVGimage ** i_svg_all_curves(void){
	static NSVGimage *curves[SVG_MEDIA_SIZE];
	int i = 0;
	//char ** media = svg_media();
	
	for (i = 0; i <  SVG_MEDIA_SIZE; i++){
		curves[i] = nsvgParse(svg_data[i], "px", 96.0f);
	}
	return curves;
}

void i_svg_free_curves(NSVGimage **curves){
	int i = 0;
	
	for (i = 0; i <  SVG_MEDIA_SIZE; i++){
		nsvgDelete(curves[i]);
	}
}

bmp_img ** i_svg_all_bmp(NSVGimage **curves, int w, int h){
	int i = 0;
	bmp_color transp = {.r = 255, .g = 255, .b = 255, .a = 0};
	bmp_color red = {.r = 255, .g = 0, .b =0, .a = 255};
	//static bmp_img * img[SVG_MEDIA_SIZE];
	bmp_img **img = malloc(sizeof(bmp_img) * SVG_MEDIA_SIZE);
	double ofs_x, ofs_y, zoom;
	
	NSVGrasterizer *rast = nsvgCreateRasterizer();
	if (rast == NULL) {
		return NULL;
	}
	
	for (i = 0; i <  SVG_MEDIA_SIZE; i++){
		img[i]  = bmp_new(w, h, transp, red);
		
		if (img[i] && curves[i]){
			img[i]->r_i = 0;
			img[i]->g_i = 1;
			img[i]->b_i = 2;
			img[i]->a_i = 3;
			img[i]->zero_tl = 1;
			bmp_fit(img[i], 0, 0, curves[i]->width, curves[i]->height, &zoom, &ofs_x, &ofs_y);
			nsvgRasterize(rast, curves[i], -ofs_x, -ofs_y, zoom, img[i]->buf, w, h, w*4);
		}
	}
	
	nsvgDeleteRasterizer(rast);
	return img;
}

bmp_img * i_svg_bmp(NSVGimage *curve, int w, int h){
	bmp_color transp = {.r = 255, .g = 255, .b = 255, .a = 0};
	bmp_color red = {.r = 255, .g = 0, .b =0, .a = 255};
	bmp_img * img;
	double ofs_x, ofs_y, zoom;
	
	NSVGrasterizer *rast = nsvgCreateRasterizer();
	if (rast == NULL) {
		return NULL;
	}
	
	img  = bmp_new(w, h, transp, red);
	
	if (img && curve){
		img->r_i = 0;
		img->g_i = 1;
		img->b_i = 2;
		img->a_i = 3;
		img->zero_tl = 1;
		bmp_fit(img, 0, 0, curve->width, curve->height, &zoom, &ofs_x, &ofs_y);
		nsvgRasterize(rast, curve, -ofs_x, -ofs_y, zoom, img->buf, w, h, w*4);
	}
	
	
	nsvgDeleteRasterizer(rast);
	return img;
}

void i_svg_free_bmp(bmp_img **img){
	int i = 0;
	
	for (i = 0; i <  SVG_MEDIA_SIZE; i++){
		bmp_free(img[i]);
	}
}
